fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    // If prefix is empty, it always matches
    if p.is_empty() {
        return true;
    }
    
    // If v is shorter than p, it cannot start with p
    if v.len() < p.len() {
        return false;
    }
    
    // Check each character in the prefix
    for i in 0..p.len() {
        if v[i] != p[i] {
            return false;
        }
    }
    
    true
}

fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    let mut filtered = Vec::new();
    
    for v in xs {
        if has_prefix(&v, &p) {
            filtered.push(v);
        }
    }
    
    filtered
}